3	 * SPDX-License-Identifier: BSD-3-Clause
4	 */
5	
6	// AscendC FusedAddRmsnorm kernel — tiled approach
7	// Fused Add + RMSNorm: y = ((hidden_states + residual) * rsqrt(mean(x^2) + eps)) * weight
8	// Uses Sqrt + reciprocal for better precision matching PyTorch rsqrt.
9	// Supports float32, float16, and bfloat16.
10	
11	#include "kernel_operator.h"
12	
13	constexpr int32_t BUFFER_NUM = 2;
14	
15	// ---------------------------------------------------------------------------
16	// Inline helpers for data movement
17	// ---------------------------------------------------------------------------
18	
19	template <typename T>
20	__aicore__ inline void LoadGmToUb(
21	    AscendC::LocalTensor<T> &dst,
22	    const AscendC::GlobalTensor<T> &src,
23	    uint32_t count)
24	{
25	    AscendC::DataCopyExtParams p{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
26	    AscendC::DataCopyPadExtParams<T> pad{true, 0, 0, static_cast<T>(0)};
27	    AscendC::DataCopyPad(dst, src, p, pad);
28	}
29	
30	template <typename T>
31	__aicore__ inline void StoreUbToGm(
32	    const AscendC::GlobalTensor<T> &dst,
33	    AscendC::LocalTensor<T> &src,
34	    uint32_t count)
35	{
36	    AscendC::DataCopyExtParams p{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
37	    AscendC::DataCopyPad(dst, src, p);
38	}
39	
40	// =========================================================================
41	// FusedAddRmsnorm Kernel — tiled processing with Sqrt+Rcp
42	// =========================================================================
43	
44	template <typename dataType>
45	class FusedAddRmsnormKernel {
46	public:
47	    __aicore__ inline void Init(
48	        GM_ADDR hidden_states, GM_ADDR residual, GM_ADDR weight, GM_ADDR output,
49	        int32_t B, int32_t H, int32_t usedCoreNum, int32_t tasksPerCore,
50	        int32_t blockM, int32_t mNum, int32_t tileH, int32_t numTilesH,
51	        int32_t lastTileH, float eps)
52	    {
53	        B_ = B; H_ = H; usedCoreNum_ = usedCoreNum; tasksPerCore_ = tasksPerCore;
54	        blockM_ = blockM; mNum_ = mNum; tileH_ = tileH;
55	        numTilesH_ = numTilesH; lastTileH_ = lastTileH; eps_ = eps;
56	
57	        uint64_t totalElem = static_cast<uint64_t>(B_) * H_;
58	        hsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(hidden_states), totalElem);
59	        resGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(residual), totalElem);
60	        wGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(weight), static_cast<uint64_t>(H_));
61	        outGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(output), totalElem);
62	
63	        pipe_.InitBuffer(hsQueue_, BUFFER_NUM, tileH_ * sizeof(dataType));
64	        pipe_.InitBuffer(resQueue_, BUFFER_NUM, tileH_ * sizeof(dataType));
65	        pipe_.InitBuffer(wQueue_, BUFFER_NUM, tileH_ * sizeof(dataType));
66	        pipe_.InitBuffer(outQueue_, BUFFER_NUM, tileH_ * sizeof(dataType));
67	
68	        pipe_.InitBuffer(hsFp32Buf_, tileH_ * sizeof(float));
69	        pipe_.InitBuffer(resFp32Buf_, tileH_ * sizeof(float));
70	        pipe_.InitBuffer(xFp32Buf_, tileH_ * sizeof(float));
71	        pipe_.InitBuffer(wFp32Buf_, tileH_ * sizeof(float));
72	        pipe_.InitBuffer(yFp32Buf_, tileH_ * sizeof(float));
73	        pipe_.InitBuffer(sqFp32Buf_, tileH_ * sizeof(float));
74	
75	        int32_t reduceWorkCount = ((tileH_ + 63) / 64) * 64;
76	        pipe_.InitBuffer(reduceWorkBuf_, reduceWorkCount * sizeof(float));
77	        pipe_.InitBuffer(sumBuf_, 16 * sizeof(float));
78	        pipe_.InitBuffer(sqSumBuf_, sizeof(float));
79	        pipe_.InitBuffer(rmsValBuf_, sizeof(float));
80	        pipe_.InitBuffer(rmsSqrtBuf_, sizeof(float));
81	    }
82	
83	    __aicore__ inline void Process()
84	    {
85	        const int coreIdx = AscendC::GetBlockIdx();
86	        for (int localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
87	            int blockId = coreIdx * tasksPerCore_ + localIdx;
88	            if (blockId >= mNum_) { continue; }
89	            int rowStart = blockId * blockM_;
90	            int actualRows = blockM_;
91	            if (blockId == mNum_ - 1) { actualRows = B_ - rowStart; }
92	            for (int rowOff = 0; rowOff < actualRows; ++rowOff) {
93	                ProcessRow(rowStart + rowOff);
94	            }
95	        }
96	    }
97	
98	private:
99	    __aicore__ inline void ProcessRow(int32_t rowIdx)
100	    {
101	        uint64_t rowOff = static_cast<uint64_t>(rowIdx) * H_;
102	
103	        // Phase 1: compute sum(x^2) over H tiles
104	        auto sqSumLocal = sqSumBuf_.Get<float>();
105	        AscendC::Duplicate(sqSumLocal, 0.0f, 1);
106	        AscendC::PipeBarrier<PIPE_V>();
107	
108	        for (int t = 0; t < numTilesH_; ++t) {
109	            int32_t tLen = (t == numTilesH_ - 1) ? lastTileH_ : tileH_;
110	            uint64_t colOff = static_cast<uint64_t>(t) * tileH_;
111	            CopyInPhase1(rowOff + colOff, tLen);
112	            ComputePhase1(tLen, t == 0);
113	        }
114	
115	        // Compute rms = 1/sqrt(sq_sum/H + eps)
116	        AscendC::PipeBarrier<PIPE_V>();
117	        float sqSum = sqSumLocal.GetValue(0);
118	        float invH = 1.0f / static_cast<float>(H_);
119	        float meanSq = sqSum * invH + eps_;
120	
121	        // Use Sqrt + reciprocal instead of Rsqrt for better precision match
122	        auto sqrtLocal = rmsSqrtBuf_.Get<float>();
123	        AscendC::Duplicate(sqrtLocal, meanSq, 1);
124	        AscendC::PipeBarrier<PIPE_ALL>();
125	        AscendC::Sqrt(sqrtLocal, sqrtLocal, 1);
126	        AscendC::PipeBarrier<PIPE_ALL>();
127	        float sqrtVal = sqrtLocal.GetValue(0);
128	        float invRms = 1.0f / sqrtVal;
129	
130	        // Phase 2: normalize and write output
131	        for (int t = 0; t < numTilesH_; ++t) {
132	            int32_t tLen = (t == numTilesH_ - 1) ? lastTileH_ : tileH_;
133	            uint64_t colOff = static_cast<uint64_t>(t) * tileH_;
134	            CopyInPhase2(rowOff + colOff, static_cast<uint32_t>(t) * tileH_, tLen);
135	            ComputePhase2(tLen, invRms);
136	            CopyOutPhase2(rowOff + colOff, tLen);
137	        }
138	    }
139	
140	    __aicore__ inline void CopyInPhase1(uint64_t rowColOff, int32_t tLen)
141	    {
142	        hsLocal_ = hsQueue_.AllocTensor<dataType>();
143	        LoadGmToUb(hsLocal_, hsGM_[rowColOff], static_cast<uint32_t>(tLen));
144	        hsQueue_.EnQue(hsLocal_);
145	
146	        resLocal_ = resQueue_.AllocTensor<dataType>();
147	        LoadGmToUb(resLocal_, resGM_[rowColOff], static_cast<uint32_t>(tLen));
148	        resQueue_.EnQue(resLocal_);
149	    }
150	
151	    __aicore__ inline void ComputePhase1(int32_t tLen, bool isFirst)
152	    {
153	        hsLocal_ = hsQueue_.DeQue<dataType>();
154	        resLocal_ = resQueue_.DeQue<dataType>();
155	
156	        auto hsFp32 = CastInput(hsFp32Buf_, hsLocal_, tLen);
157	        auto resFp32 = CastInput(resFp32Buf_, resLocal_, tLen);
158	
159	        auto xFp32 = xFp32Buf_.Get<float>(tLen);
160	        AscendC::Add(xFp32, hsFp32, resFp32, tLen);
161	
162	        auto sqFp32 = sqFp32Buf_.Get<float>(tLen);
163	        AscendC::Mul(sqFp32, xFp32, xFp32, tLen);
164	
165	        auto reduceWork = reduceWorkBuf_.Get<float>();
166	        // Initialize work buffer for first tile
167	        if (isFirst) {
168	            AscendC::Duplicate(reduceWork, 0.0f, ((tLen + 63) / 64) * 64);
169	            AscendC::PipeBarrier<PIPE_V>();
170	        }
171	        auto sumLocal = sumBuf_.Get<float>();
172	        AscendC::ReduceSum<float>(sumLocal, sqFp32, reduceWork, tLen);
173	        AscendC::PipeBarrier<PIPE_V>();
174	
175	        auto sqSumLocal = sqSumBuf_.Get<float>();
176	        AscendC::Adds(sqSumLocal, sqSumLocal, sumLocal.GetValue(0), 1);
177	        AscendC::PipeBarrier<PIPE_V>();
178	
179	        hsQueue_.FreeTensor(hsLocal_);
180	        resQueue_.FreeTensor(resLocal_);
181	    }
182	
183	    __aicore__ inline void CopyInPhase2(uint64_t rowColOff, uint32_t wOff, int32_t tLen)
184	    {
185	        hsLocal_ = hsQueue_.AllocTensor<dataType>();
186	        LoadGmToUb(hsLocal_, hsGM_[rowColOff], static_cast<uint32_t>(tLen));
187	        hsQueue_.EnQue(hsLocal_);
188	
189	        resLocal_ = resQueue_.AllocTensor<dataType>();
190	        LoadGmToUb(resLocal_, resGM_[rowColOff], static_cast<uint32_t>(tLen));
191	        resQueue_.EnQue(resLocal_);
192	
193	        wLocal_ = wQueue_.AllocTensor<dataType>();
194	        LoadGmToUb(wLocal_, wGM_[wOff], static_cast<uint32_t>(tLen));
195	        wQueue_.EnQue(wLocal_);
196	    }
197	
198	    __aicore__ inline void ComputePhase2(int32_t tLen, float invRms)
199	    {
200	        outLocal_ = outQueue_.AllocTensor<dataType>();
201	        hsLocal_ = hsQueue_.DeQue<dataType>();
202	        resLocal_ = resQueue_.DeQue<dataType>();
203	        wLocal_ = wQueue_.DeQue<dataType>();
204	
205	        auto hsFp32 = CastInput(hsFp32Buf_, hsLocal_, tLen);
206	        auto resFp32 = CastInput(resFp32Buf_, resLocal_, tLen);
207	        auto wFp32 = CastInput(wFp32Buf_, wLocal_, tLen);
208	
209	        auto xFp32 = xFp32Buf_.Get<float>(tLen);
210	        AscendC::Add(xFp32, hsFp32, resFp32, tLen);
211	
212	        auto yFp32 = yFp32Buf_.Get<float>(tLen);
213	        AscendC::Muls(yFp32, xFp32, invRms, tLen);
214	        AscendC::Mul(yFp32, yFp32, wFp32, tLen);
215	
216	        CastOutput(outLocal_, yFp32, tLen);
217	        AscendC::PipeBarrier<PIPE_V>();
218	
219	        hsQueue_.FreeTensor(hsLocal_);
220	        resQueue_.FreeTensor(resLocal_);
221	        wQueue_.FreeTensor(wLocal_);
222	        outQueue_.EnQue(outLocal_);
223	    }
224	
225	    __aicore__ inline void CopyOutPhase2(uint64_t rowColOff, int32_t tLen)
226	    {
227	        outLocal_ = outQueue_.DeQue<dataType>();
228	        StoreUbToGm(outGM_[rowColOff], outLocal_, static_cast<uint32_t>(tLen));
229	        outQueue_.FreeTensor(outLocal_);
230	    }
231	
232	    template <typename SrcT>
233	    __aicore__ inline AscendC::LocalTensor<float> CastInput(
234	        AscendC::TBuf<AscendC::TPosition::VECCALC> &buf,
235	        AscendC::LocalTensor<SrcT> &src, int32_t count)
236	    {
237	        if constexpr (std::is_same_v<SrcT, float>) {
238	            return src.template ReinterpretCast<float>();
239	        } else {
240	            auto dst = buf.Get<float>(count);
241	            AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
242	            AscendC::PipeBarrier<PIPE_V>();
243	            return dst;
244	        }
245	    }
246	
247	    template <typename DstT>
248	    __aicore__ inline void CastOutput(
249	        AscendC::LocalTensor<DstT> &dst,
250	        AscendC::LocalTensor<float> &src, int32_t count)
251	    {
252	        if constexpr (std::is_same_v<DstT, float>) {
253	            AscendC::DataCopy(dst, src, count);
254	        } else {
255	            AscendC::RoundMode rm = AscendC::RoundMode::CAST_ROUND;
256	            AscendC::Cast(dst, src, rm, count);
257	            AscendC::PipeBarrier<PIPE_V>();
258	        }
259	    }
260	
261	    int32_t B_, H_, usedCoreNum_, tasksPerCore_, blockM_, mNum_;
262	    int32_t tileH_, numTilesH_, lastTileH_;
263	    float eps_;
264	    AscendC::TPipe pipe_;
265	    AscendC::GlobalTensor<dataType> hsGM_, resGM_, wGM_, outGM_;
266	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> hsQueue_, resQueue_, wQueue_;
267	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;
268	    AscendC::TBuf<AscendC::TPosition::VECCALC> hsFp32Buf_, resFp32Buf_, xFp32Buf_;
269	    AscendC::TBuf<AscendC::TPosition::VECCALC> wFp32Buf_, yFp32Buf_, sqFp32Buf_;
270	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceWorkBuf_, sumBuf_;
271	    AscendC::TBuf<AscendC::TPosition::VECCALC> sqSumBuf_, rmsValBuf_, rmsSqrtBuf_;
272	    AscendC::LocalTensor<dataType> hsLocal_, resLocal_, wLocal_, outLocal_;
273	};
