22	at::Tensor fused_add_rmsnorm(
23	    const at::Tensor &hidden_states,
24	    const at::Tensor &residual,
25	    const at::Tensor &weight,
26	    double eps)
27	{
28	    // Input validation
29	    TORCH_CHECK(hidden_states.dim() == 2, "hidden_states must be 2D [B, H]");
30	    TORCH_CHECK(residual.dim() == 2, "residual must be 2D [B, H]");
31	    TORCH_CHECK(weight.dim() == 1, "weight must be 1D [H]");
32	    TORCH_CHECK(
33	        hidden_states.scalar_type() == at::kFloat ||
34	        hidden_states.scalar_type() == at::kHalf ||
35	        hidden_states.scalar_type() == at::kBFloat16,
36	        "hidden_states must be float32, float16, or bfloat16");
37	    TORCH_CHECK(hidden_states.sizes() == residual.sizes(),
38	        "hidden_states and residual must have the same shape");
39	    TORCH_CHECK(hidden_states.sizes()[1] == weight.sizes()[0],
40	        "hidden_states dim 1 must match weight size");
41	
42	    int32_t B = static_cast<int32_t>(hidden_states.sizes()[0]);
43	    int32_t H = static_cast<int32_t>(hidden_states.sizes()[1]);
44	
45	    // Platform info
46	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
47	    int32_t numCores = static_cast<int32_t>(ascendcPlatform->GetCoreNumAiv());
48	    uint64_t ubSize = 0;
49	    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
50	
51	    // dtype flag: 0=fp32, 1=fp16, 2=bf16
52	    int64_t dtypeFlag = 0;
53	    int32_t dtypeSize = 4;
54	    int32_t bufferCoefficient = 64;
55	
56	    if (hidden_states.scalar_type() == at::kHalf) {
57	        dtypeFlag = 1;
58	        dtypeSize = 2;
59	        bufferCoefficient = 48;
60	    } else if (hidden_states.scalar_type() == at::kBFloat16) {
61	        dtypeFlag = 2;
62	        dtypeSize = 2;
63	        bufferCoefficient = 48;
64	    }
65	
66	    // Block-level tiling
67	    int32_t blockM = 64;
68	    int32_t mNum = B / blockM;
69	    if (mNum == 0) {
70	        mNum = 1;
71	        blockM = B;
72	    }
73	    int32_t usedCoreNum = std::min(numCores, mNum);
74	    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;
75	
76	    // UB-level tiling
77	    int32_t maxTileH = static_cast<int32_t>(ubSize) / (bufferCoefficient * dtypeSize);
78	    int32_t tileH = std::min(H, maxTileH);
79	    int32_t alignElem = 32 / dtypeSize;
80	    tileH = (tileH / alignElem) * alignElem;
81	    if (tileH < 1) { tileH = alignElem; }
82	    int32_t numTilesH = H / tileH;
83	    int32_t lastTileH = H - numTilesH * tileH;
84	    if (lastTileH == 0) {
85	        lastTileH = tileH;
86	    } else {
87	        numTilesH += 1;
88	    }
89	
90	    // Create output tensor
91	    auto output = at::empty_like(hidden_states);
92	
93	    // All parameters must be left-values for EXEC_KERNEL_CMD
94	    float epsVal = static_cast<float>(eps);
95	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
96	
97	    EXEC_KERNEL_CMD(fused_add_rmsnorm_kernel, blockDim,
98	                    hidden_states, residual, weight, output,
99	                    B, H, usedCoreNum, tasksPerCore,
100	                    blockM, mNum, tileH, numTilesH, lastTileH,
101	                    epsVal, dtypeFlag);
102	
103	    return output;
104	}
