// AscendC GaussianTopkSparseActivation kernel
// Computes: threshold = mean(input) + std(input) * ndtri_value
//           output = relu(input - threshold), cast to bfloat16
// Support: float32 / float16 / bfloat16 input, always bfloat16 output

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// ---------------------------------------------------------------------------
// Inline helpers for data movement
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    const AscendC::GlobalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams p{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> pad{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, p, pad);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    const AscendC::GlobalTensor<T> &dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams p{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, p);
}

// =========================================================================
// GaussianTopkSparseActivation Kernel
// =========================================================================

template <typename dataType>
class GaussianTopkSparseActivationKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR input, GM_ADDR output,
        int32_t M, int32_t D, int32_t usedCoreNum, int32_t tasksPerCore,
        int32_t blockM, int32_t mNum, int32_t tileD, int32_t numTilesD,
        int32_t lastTileD, float ndtriValue)
    {
        M_ = M; D_ = D; usedCoreNum_ = usedCoreNum; tasksPerCore_ = tasksPerCore;
        blockM_ = blockM; mNum_ = mNum; tileD_ = tileD;
        numTilesD_ = numTilesD; lastTileD_ = lastTileD; ndtriValue_ = ndtriValue;

        float invDVal = 1.0f / static_cast<float>(D_);
        invD_ = invDVal;

        uint64_t totalElem = static_cast<uint64_t>(M_) * D_;
        inputGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(input), totalElem);
        outputGM_.SetGlobalBuffer(reinterpret_cast<__gm__ bfloat16_t *>(output), totalElem);

        // TQue buffers for GM<->UB data movement
        pipe_.InitBuffer(inQueue_, BUFFER_NUM, tileD_ * sizeof(dataType));
        pipe_.InitBuffer(outQueue_, BUFFER_NUM, tileD_ * sizeof(bfloat16_t));

        // TBuf buffers for intermediate computation (VECCALC)
        pipe_.InitBuffer(inFp32Buf_, tileD_ * sizeof(float));
        pipe_.InitBuffer(sqFp32Buf_, tileD_ * sizeof(float));
        pipe_.InitBuffer(shiftedBuf_, tileD_ * sizeof(float));
        pipe_.InitBuffer(activatedBuf_, tileD_ * sizeof(float));

        // Reduction buffers
        int32_t reduceWorkCount = ((tileD_ + 63) / 64) * 64;
        pipe_.InitBuffer(reduceWorkBuf_, reduceWorkCount * sizeof(float));
        pipe_.InitBuffer(reduceOutBuf_, 16 * sizeof(float));

        // Accumulator buffers (scalar values kept in UB)
        pipe_.InitBuffer(sumAccBuf_, sizeof(float));
        pipe_.InitBuffer(sqAccBuf_, sizeof(float));
        pipe_.InitBuffer(meanBuf_, sizeof(float));
        pipe_.InitBuffer(stdBuf_, sizeof(float));
        pipe_.InitBuffer(threshBuf_, sizeof(float));
    }

    __aicore__ inline void Process()
    {
        const int coreIdx = AscendC::GetBlockIdx();
        for (int localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
            int blockId = coreIdx * tasksPerCore_ + localIdx;
            if (blockId >= mNum_) { continue; }
            int rowStart = blockId * blockM_;
            int actualRows = blockM_;
            if (blockId == mNum_ - 1) { actualRows = M_ - rowStart; }
            for (int rowOff = 0; rowOff < actualRows; ++rowOff) {
                ProcessRow(rowStart + rowOff);
            }
        }
    }

private:
    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        uint64_t rowOff = static_cast<uint64_t>(rowIdx) * D_;

        // Initialize accumulators
        auto sumAccLocal = sumAccBuf_.Get<float>();
        AscendC::Duplicate(sumAccLocal, 0.0f, 1);
        auto sqAccLocal = sqAccBuf_.Get<float>();
        AscendC::Duplicate(sqAccLocal, 0.0f, 1);
        AscendC::PipeBarrier<PIPE_V>();

        // ===== Phase 1: accumulate sum and sum_sq over D =====
        for (int t = 0; t < numTilesD_; ++t) {
            int32_t tLen = (t == numTilesD_ - 1) ? lastTileD_ : tileD_;
            uint64_t colOff = static_cast<uint64_t>(t) * tileD_;
            CopyInPhase1(rowOff + colOff, tLen);
            ComputePhase1(tLen, t == 0);
        }

        // ===== Compute threshold: mean + std * ndtri =====
        // Use Sqrt + reciprocal instead of Rsqrt for better precision
        AscendC::PipeBarrier<PIPE_V>();
        float sumVal = sumAccLocal.GetValue(0);
        float sqVal = sqAccLocal.GetValue(0);

        // mean = sum / D
        float rowMeanVal = sumVal * invD_;
        // mean_sq = sum_sq / D
        float meanSqVal = sqVal * invD_;
        // var = mean_sq - mean * mean
        float rowVarVal = meanSqVal - rowMeanVal * rowMeanVal;
        if (rowVarVal < 0.0f) { rowVarVal = 0.0f; }

        // std = sqrt(var)
        auto stdLocal = stdBuf_.Get<float>();
        AscendC::Duplicate(stdLocal, rowVarVal, 1);
        AscendC::PipeBarrier<PIPE_ALL>();
        AscendC::Sqrt(stdLocal, stdLocal, 1);
        AscendC::PipeBarrier<PIPE_ALL>();
        float rowStdVal = stdLocal.GetValue(0);

        // threshold = mean + std * ndtri
        float rowThreshVal = rowMeanVal + rowStdVal * ndtriValue_;

        // ===== Phase 2: relu(input - threshold), cast, store =====
        for (int t = 0; t < numTilesD_; ++t) {
            int32_t tLen = (t == numTilesD_ - 1) ? lastTileD_ : tileD_;
            uint64_t colOff = static_cast<uint64_t>(t) * tileD_;
            CopyInPhase2(rowOff + colOff, tLen);
            ComputePhase2(tLen, rowThreshVal);
            CopyOutPhase2(rowOff + colOff, tLen);
        }
    }

    __aicore__ inline void CopyInPhase1(uint64_t rowColOff, int32_t tLen)
    {
        inLocal_ = inQueue_.AllocTensor<dataType>();
        LoadGmToUb(inLocal_, inputGM_[rowColOff], static_cast<uint32_t>(tLen));
        inQueue_.EnQue(inLocal_);
    }

    __aicore__ inline void ComputePhase1(int32_t tLen, bool isFirst)
    {
        inLocal_ = inQueue_.DeQue<dataType>();

        // Cast to fp32
        auto inFp32 = CastToFp32(inFp32Buf_, inLocal_, tLen);

        // Square: x^2
        auto sqFp32 = sqFp32Buf_.Get<float>(tLen);
        AscendC::Mul(sqFp32, inFp32, inFp32, tLen);

        auto reduceWork = reduceWorkBuf_.Get<float>();
        int32_t workCount = ((tLen + 63) / 64) * 64;
        // Initialize work buffer for first tile
        if (isFirst) {
            AscendC::Duplicate(reduceWork, 0.0f, workCount);
            AscendC::PipeBarrier<PIPE_V>();
        }

        // Reduce sum of input
        auto reduceOut = reduceOutBuf_.Get<float>();
        AscendC::ReduceSum<float>(reduceOut, inFp32, reduceWork, tLen);
        AscendC::PipeBarrier<PIPE_V>();

        auto sumAccLocal = sumAccBuf_.Get<float>();
        AscendC::Adds(sumAccLocal, sumAccLocal, reduceOut.GetValue(0), 1);
        AscendC::PipeBarrier<PIPE_V>();

        // Reduce sum of squares
        // Re-init work buffer
        AscendC::Duplicate(reduceWork, 0.0f, workCount);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::ReduceSum<float>(reduceOut, sqFp32, reduceWork, tLen);
        AscendC::PipeBarrier<PIPE_V>();

        auto sqAccLocal = sqAccBuf_.Get<float>();
        AscendC::Adds(sqAccLocal, sqAccLocal, reduceOut.GetValue(0), 1);
        AscendC::PipeBarrier<PIPE_V>();

        inQueue_.FreeTensor(inLocal_);
    }

    __aicore__ inline void CopyInPhase2(uint64_t rowColOff, int32_t tLen)
    {
        inLocal_ = inQueue_.AllocTensor<dataType>();
        LoadGmToUb(inLocal_, inputGM_[rowColOff], static_cast<uint32_t>(tLen));
        inQueue_.EnQue(inLocal_);
    }

    __aicore__ inline void ComputePhase2(int32_t tLen, float thresholdVal)
    {
        outLocal_ = outQueue_.AllocTensor<bfloat16_t>();
        inLocal_ = inQueue_.DeQue<dataType>();

        // Cast to fp32
        auto inFp32 = CastToFp32(inFp32Buf_, inLocal_, tLen);

        // shifted = input - threshold  (scalar broadcast)
        auto shiftedFp32 = shiftedBuf_.Get<float>(tLen);
        AscendC::Adds(shiftedFp32, inFp32, -thresholdVal, tLen);

        // activated = relu(shifted)
        auto activatedFp32 = activatedBuf_.Get<float>(tLen);
        AscendC::Relu(activatedFp32, shiftedFp32, tLen);

        // Cast to bfloat16
        AscendC::Cast(outLocal_, activatedFp32, AscendC::RoundMode::CAST_ROUND, tLen);
        AscendC::PipeBarrier<PIPE_V>();

        inQueue_.FreeTensor(inLocal_);
        outQueue_.EnQue(outLocal_);
    }

    __aicore__ inline void CopyOutPhase2(uint64_t rowColOff, int32_t tLen)
    {
        outLocal_ = outQueue_.DeQue<bfloat16_t>();
        StoreUbToGm(outputGM_[rowColOff], outLocal_, static_cast<uint32_t>(tLen));
        outQueue_.FreeTensor(outLocal_);
    }

    // -----------------------------------------------------------------------
    // Helper: Cast input to fp32
    // -----------------------------------------------------------------------
    template <typename SrcT>
    __aicore__ inline AscendC::LocalTensor<float> CastToFp32(
        AscendC::TBuf<AscendC::TPosition::VECCALC> &buf,
        AscendC::LocalTensor<SrcT> &src, int32_t count)
    {
        if constexpr (std::is_same_v<SrcT, float>) {
            return src.template ReinterpretCast<float>();
        } else {
            auto dst = buf.Get<float>(count);
            AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
            AscendC::PipeBarrier<PIPE_V>();
            return dst;
        }
    }

    int32_t M_, D_, usedCoreNum_, tasksPerCore_, blockM_, mNum_;
    int32_t tileD_, numTilesD_, lastTileD_;
    float ndtriValue_, invD_;
    AscendC::TPipe pipe_;
    AscendC::GlobalTensor<dataType> inputGM_;
    AscendC::GlobalTensor<bfloat16_t> outputGM_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> inFp32Buf_, sqFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> shiftedBuf_, activatedBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceWorkBuf_, reduceOutBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumAccBuf_, sqAccBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> meanBuf_, stdBuf_, threshBuf_;
    AscendC::LocalTensor<dataType> inLocal_;
    AscendC::LocalTensor<bfloat16_t> outLocal_;
};

extern "C" __global__ __aicore__ void gaussian_topk_sparse_activation_kernel(
    GM_ADDR input, GM_ADDR output,
    int32_t M, int32_t D, int32_t usedCoreNum, int32_t tasksPerCore,
    int32_t blockM, int32_t mNum, int32_t tileD, int32_t numTilesD,
    int32_t lastTileD, float ndtriValue, int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        GaussianTopkSparseActivationKernel<float> k;
        k.Init(input, output, M, D, usedCoreNum, tasksPerCore,
               blockM, mNum, tileD, numTilesD, lastTileD, ndtriValue);
        k.Process();
    } else if (dtypeFlag == 1) {
        GaussianTopkSparseActivationKernel<half> k;
        k.Init(input, output, M, D, usedCoreNum, tasksPerCore,
               blockM, mNum, tileD, numTilesD, lastTileD, ndtriValue);
        k.Process();
    } else {
        GaussianTopkSparseActivationKernel<bfloat16_t> k;
        k.Init(input, output, M, D, usedCoreNum, tasksPerCore,
               blockM, mNum, tileD, numTilesD, lastTileD, ndtriValue);
        k.Process();
    }
}
