#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_gaussian_topk_sparse_activation_kernel.h"

namespace {

// Abramowitz & Stegun constants for ndtri (inverse normal CDF)
constexpr double A1 = -3.969683028665376e01;
constexpr double A2 =  2.209460984245205e02;
constexpr double A3 = -2.759285104469687e02;
constexpr double A4 =  1.383577518672690e02;
constexpr double A5 = -3.066479806614716e01;
constexpr double A6 =  2.506628277459239e00;

constexpr double B1 = -5.447609879822406e01;
constexpr double B2 =  1.615858368580409e02;
constexpr double B3 = -1.556989798598866e02;
constexpr double B4 =  6.680131188771972e01;
constexpr double B5 = -1.328068155288572e01;

constexpr double C1 = -7.784894002430293e-03;
constexpr double C2 = -3.223964580411365e-01;
constexpr double C3 = -2.400758277161838e00;
constexpr double C4 = -2.549732539343734e00;
constexpr double C5 =  4.374664141464968e00;
constexpr double C6 =  2.938163982698783e00;

constexpr double D1 =  7.784695709041462e-03;
constexpr double D2 =  3.224671290700398e-01;
constexpr double D3 =  2.445134137142996e00;
constexpr double D4 =  3.754408661907416e00;

constexpr double P_LOW = 0.02425;
constexpr double P_HIGH = 1.0 - P_LOW;

float ComputeNdtri(double p) {
    // Clamp p to avoid domain errors
    if (p <= 0.0) p = 1e-15;
    if (p >= 1.0) p = 1.0 - 1e-15;

    double result;
    if (p < P_LOW) {
        double q = std::sqrt(-2.0 * std::log(p));
        double num = (((((C1 * q + C2) * q + C3) * q + C4) * q + C5) * q + C6);
        double den = ((((D1 * q + D2) * q + D3) * q + D4) * q + 1.0);
        result = num / den;
    } else if (p <= P_HIGH) {
        double q = p - 0.5;
        double r = q * q;
        double num = (((((A1 * r + A2) * r + A3) * r + A4) * r + A5) * r + A6) * q;
        double den = (((((B1 * r + B2) * r + B3) * r + B4) * r + B5) * r + 1.0);
        result = num / den;
    } else {
        double q = std::sqrt(-2.0 * std::log(1.0 - p));
        double num = (((((C1 * q + C2) * q + C3) * q + C4) * q + C5) * q + C6);
        double den = ((((D1 * q + D2) * q + D3) * q + D4) * q + 1.0);
        result = -num / den;
    }
    return static_cast<float>(result);
}

}  // anonymous namespace

namespace ascend_kernel {

at::Tensor gaussian_topk_sparse_activation(
    const at::Tensor &inputs,
    double target_sparsity)
{
    // Input validation
    TORCH_CHECK(inputs.dim() == 3, "inputs must be 3D [B, S, D]");
    TORCH_CHECK(
        inputs.scalar_type() == at::kFloat ||
        inputs.scalar_type() == at::kHalf ||
        inputs.scalar_type() == at::kBFloat16,
        "inputs must be float32, float16, or bfloat16");

    int32_t B = static_cast<int32_t>(inputs.sizes()[0]);
    int32_t S = static_cast<int32_t>(inputs.sizes()[1]);
    int32_t D = static_cast<int32_t>(inputs.sizes()[2]);
    int32_t M = B * S;

    // Precompute ndtri on host
    float ndtriValue = ComputeNdtri(target_sparsity);

    // Platform info
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int32_t numCores = static_cast<int32_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize = 0;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    int32_t dtypeSize = 4;
    int32_t bufferCoefficient = 72;

    if (inputs.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
        dtypeSize = 2;
        bufferCoefficient = 56;
    } else if (inputs.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
        dtypeSize = 2;
        bufferCoefficient = 56;
    }

    // Block-level tiling: split M dimension across cores
    int32_t blockM = 64;
    if (D <= 1024) {
        blockM = 32;
    }
    int32_t mNum = M / blockM;
    if (mNum == 0) {
        mNum = 1;
        blockM = M;
    }
    int32_t usedCoreNum = std::min(numCores, mNum);
    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;

    // UB-level tiling: tile size along D dimension
    int32_t maxTileD = static_cast<int32_t>(ubSize) / (bufferCoefficient * dtypeSize);
    int32_t tileD = std::min(D, maxTileD);
    int32_t alignElem = 32 / dtypeSize;
    if (alignElem < 1) { alignElem = 8; }
    tileD = (tileD / alignElem) * alignElem;
    if (tileD < 1) { tileD = alignElem; }

    int32_t numTilesD = D / tileD;
    int32_t lastTileD = D - numTilesD * tileD;
    if (lastTileD == 0) {
        lastTileD = tileD;
    } else {
        numTilesD += 1;
    }

    // Create output tensor (always bfloat16)
    auto output = at::empty({B, S, D},
        inputs.options().dtype(at::kBFloat16));

    // All parameters must be left-values for EXEC_KERNEL_CMD
    float ndtriValLv = ndtriValue;
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(gaussian_topk_sparse_activation_kernel, blockDim,
                    inputs, output,
                    M, D, usedCoreNum, tasksPerCore,
                    blockM, mNum, tileD, numTilesD, lastTileD,
                    ndtriValLv, dtypeFlag);

    return output;
}

}  // namespace ascend_kernel
